package ru.mirea.conference.fx.controller;
import javafx.collections.FXCollections; import javafx.fxml.FXML; import javafx.scene.control.*; import javafx.stage.Stage; import javafx.util.StringConverter; import ru.mirea.conference.model.*; import java.util.List;
public class RegistrationFormController {
 @FXML private ComboBox<Participant> participant; @FXML private ComboBox<Conference> conference; @FXML private ComboBox<RegistrationStatus> status; private Registration result;
 @FXML private void initialize(){status.getItems().setAll(RegistrationStatus.values()); status.setValue(RegistrationStatus.CREATED); status.setDisable(true);participant.setConverter(new StringConverter<>(){public String toString(Participant p){return p==null?"":p.getFullName()+" — "+p.getEmail();}public Participant fromString(String s){return null;}});conference.setConverter(new StringConverter<>(){public String toString(Conference c){return c==null?"":c.getTitle()+" — "+c.getStartDate();}public Conference fromString(String s){return null;}});}
 public void setParticipants(List<Participant> p){participant.setItems(FXCollections.observableArrayList(p));}
 public void setConferences(List<Conference> c){conference.setItems(FXCollections.observableArrayList(c));}
 public void setExisting(Registration r){status.setDisable(false);result=new Registration(r.getId(),r.getParticipantId(),r.getConferenceId(),r.getStatus(),r.getRegisteredAt());participant.getItems().stream().filter(x->x.getId().equals(r.getParticipantId())).findFirst().ifPresent(participant::setValue);conference.getItems().stream().filter(x->x.getId().equals(r.getConferenceId())).findFirst().ifPresent(conference::setValue);status.setValue(r.getStatus());}
 @FXML private void save(){if(participant.getValue()==null){Ui.error("Ошибка","Выберите участника.");return;}if(conference.getValue()==null){Ui.error("Ошибка","Выберите конференцию.");return;}if(status.getValue()==null){Ui.error("Ошибка","Выберите статус.");return;}if(result==null)result=new Registration(participant.getValue().getId(),conference.getValue().getId(),status.getValue());else{result.setParticipantId(participant.getValue().getId());result.setConferenceId(conference.getValue().getId());result.setStatus(status.getValue());}close();}
 @FXML private void cancel(){result=null;close();} private void close(){((Stage)participant.getScene().getWindow()).close();} public Registration getResult(){return result;}
}